import sys

def main():
    lines = sys.stdin.read().splitlines()
    home = lines[0].split("=")[1].strip()

    for raw in lines[1:]:
        if not raw.strip():
            continue

        fields = raw.strip().split(";")
        title = fields[0].strip() if fields else ""
        first = fields[1].strip() if len(fields) > 1 else ""
        last = fields[2].strip() if len(fields) > 2 else ""
        street = fields[3].strip() if len(fields) > 3 else ""
        postcode = fields[4].strip() if len(fields) > 4 else ""
        city = fields[5].strip() if len(fields) > 5 else ""
        country = fields[6].strip() if len(fields) > 6 else ""

        name_line = f"{title} {first} {last}".strip()
        if not first and not last:
            name_line = "To the occupant"

        if name_line:
            print(name_line)

        if street.strip():
            print(street)

        if postcode.strip() and city.strip():
            print(f"{postcode} {city}")

        if country.strip() and country.upper() != home.upper():
            print(country.upper())

        if not (street.strip() and postcode.strip() and city.strip()):
            print("---")


if __name__ == "__main__":
    main()
